// Where a special page can go in the page list, and what placing it there writes (feedback K13).
//
// The page list (`ui/pagelist.js`) offers a „+“ between the pages wherever a special page can be
// inserted and lets the designer drag special pages: front special pages sit between the cover
// and the first week page, back ones between the last week page and the back. Week pages are
// generated by date, so nothing goes between them.
//
// A slot is `{ position: 'front' | 'back', index }` — `index` counts the special pages that are
// shown (on) in that section before the slot. `pos` is one order over every special page (front,
// back, on and off alike — `orderedSpecialPages`), so a page is placed next to a shown neighbour
// and the whole collection is renumbered with `reorder()`; pages that are off keep their order
// among the rest.
//
// Pure: no DOM, nothing mutated. Lives in `state/` (not `generate/`) on purpose: it is an editing
// helper, and nothing under `generate/` may change without moving the export fingerprint
// (`CalendarModuleInliner::DIRECTORIES`).

import { reorder } from '../model/content.js';
import { orderedSpecialPages } from '../generate/pages.js';

const sectionOf = (item) => (item.position === 'back' ? 'back' : 'front');

/**
 * The special pages that are shown, per section, in page order: `{ front: [id…], back: [id…] }`.
 * With the feature off nothing is shown.
 */
export function specialSections(doc) {
    const out = { front: [], back: [] };
    if (!doc.design.features.specialPages) return out;
    for (const [id, item] of orderedSpecialPages(doc.content)) {
        if (item.on) out[sectionOf(item)].push(id);
    }
    return out;
}

/**
 * Every slot of the page list, in page order: after the cover / each front special page, and
 * after the last week page / each back special page. `after` is the page key the slot follows.
 */
export function specialSlots(doc) {
    const sections = specialSections(doc);
    const slots = [];
    const section = (position, first) => {
        slots.push({ position, index: 0, after: first });
        sections[position].forEach((id, i) => slots.push({ position, index: i + 1, after: `sp:${id}` }));
    };
    section('front', 'cover');
    section('back', 'weeks');
    return slots;
}

/**
 * Places special page `id` at `slot` and switches it on: the items to write, `{ id: item }` —
 * only those that change. `item` = the page's new fields (a page being created, or an uploaded
 * file replacing them); otherwise the stored item (or the default of a generated kind) is used.
 * Returns `{}` when the page is already there.
 */
export function placeSpecial(doc, id, slot, item = null) {
    const all = Object.fromEntries(orderedSpecialPages(doc.content));
    const base = item || all[id];
    if (!base) return {};
    const position = slot.position === 'back' ? 'back' : 'front';
    const moved = { ...base, on: true, position };
    const featureOn = Boolean(doc.design.features.specialPages);

    const order = Object.keys(all).filter((other) => other !== id);
    // shown neighbours in the target section (the page itself left out)
    const shown = order.filter((other) => featureOn && all[other].on && sectionOf(all[other]) === position);
    const index = Math.max(0, Math.min(shown.length, Math.floor(Number(slot.index) || 0)));
    let at;
    if (index > 0) at = order.indexOf(shown[index - 1]) + 1;
    else if (shown.length) at = order.indexOf(shown[0]);
    else at = position === 'front' ? 0 : order.length;
    order.splice(at, 0, id);

    // already shown right there: nothing to write
    if (!item && featureOn && base.on && sectionOf(base) === position && specialSections(doc)[position].indexOf(id) === index) return {};

    const collection = { ...all, [id]: moved };
    const changed = reorder(collection, order);
    const stored = doc.content.specialPages && doc.content.specialPages[id];
    const result = changed[id] || moved;
    const same = stored && JSON.stringify(stored) === JSON.stringify(result);
    if (!same) changed[id] = result;
    else delete changed[id];
    return changed;
}

/**
 * The slot a dragged page was dropped into, read from the list's new order: `sequence` is the
 * pages as they now stand — `'cover'`, `'week'`, `'back'` or a special page id (insertion points
 * and anything else may be passed as `null`, they are skipped). A page after any week page is in
 * the back section. `null` when `id` is not in the sequence.
 */
export function slotInSequence(sequence, id) {
    let position = 'front';
    let index = 0;
    for (const token of sequence) {
        if (token === null || token === undefined || token === 'cover') continue;
        if (token === id) return { position, index };
        if (token === 'week' || token === 'back') {
            if (token === 'week' && position === 'front') {
                position = 'back';
                index = 0;
            }
            continue;
        }
        index++;
    }
    return null;
}
